function Assert-FndWorkspace {
  $expected='C:\LabEx\Labs\'+$labId
  if([IO.Path]::GetFullPath($labRoot) -ne $expected){throw 'Unexpected lab root'}
  foreach($path in @('C:\LabEx','C:\LabEx\Labs',$labRoot)){
    if((Test-Path -LiteralPath $path) -and ((Get-Item -LiteralPath $path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint)){throw 'Reparse path refused'}
  }
  if((Test-Path -LiteralPath $labRoot) -and @(Get-ChildItem -LiteralPath $labRoot -Force -Recurse | Where-Object {$_.Attributes -band [IO.FileAttributes]::ReparsePoint}).Count){throw 'Reparse item refused'}
}
Assert-FndWorkspace
New-Item -ItemType Directory -Path $labRoot -Force | Out-Null
function Get-NwfRoutes {
  return @(Get-NetRoute -AddressFamily IPv4 | Sort-Object InterfaceIndex,DestinationPrefix,NextHop,RouteMetric | ForEach-Object {
    "$($_.InterfaceIndex)|$($_.DestinationPrefix)|$($_.NextHop)|$($_.RouteMetric)"
  })
}
function Get-NwfSubnet([string]$address,[int]$prefix){
  if($prefix -lt 0 -or $prefix -gt 32 -or $address -notmatch '^\d{1,3}(\.\d{1,3}){3}$'){throw 'IPv4/prefix invalid'}
  $ip=[Net.IPAddress]::Parse($address)
  $bytes=$ip.GetAddressBytes();[uint64]$number=0
  foreach($b in $bytes){$number=($number*256)+$b}
  [uint64]$size=[Math]::Pow(2,32-$prefix)
  [uint64]$network=[Math]::Floor($number/$size)*$size
  [uint64]$last=$network+$size-1
  $firstText=(@(24,16,8,0)|ForEach-Object {[string](($network -shr $_) -band 255)}) -join '.'
  $lastText=(@(24,16,8,0)|ForEach-Object {[string](($last -shr $_) -band 255)}) -join '.'
  [pscustomobject]@{Network=$firstText;LastAddress=$lastText;Prefix=$prefix}
}
$subnet=Get-NwfSubnet '10.20.30.45' 26
$data=[pscustomobject]@{Routes=@(Get-NwfRoutes);Exercise=[pscustomobject]@{Address='10.20.30.45';Prefix=26;Network=$subnet.Network;LastAddress=$subnet.LastAddress;UsableHosts=62;GatewayExample='10.20.30.1';OtherSubnetExample='10.20.30.99'}}
[pscustomobject]@{Schema=1;LabId=$labId;Computer=$env:COMPUTERNAME;CollectedAtUtc=[DateTimeOffset]::UtcNow.ToString('o');Data=$data} | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $labRoot 'step2.json') -Encoding UTF8
Write-Output 'Da ghi step2.json; xem Data trong thu muc bai.'

